class CMS {
  constructor(w, d) {
    this.w = w; this.d = d;
    this.table = Array.from({ length: d }, () => new Array(w).fill(0));
  }
  // use independent hash seeds per depth
  add(x, c = 1) { for (let i = 0; i < this.d; i++) { const idx = hashSeeded(x, i) % this.w; this.table[i][idx] += c; } }
  estimate(x) { let min = Infinity; for (let i = 0; i < this.d; i++) { const idx = hashSeeded(x, i) % this.w; min = Math.min(min, this.table[i][idx]); } return min; }
}
function hashSeeded(x, seed) {
  // simple placeholder; in practice use a strong 64-bit hash with seed
  let h = x ^ seed; h = (h * 0x9e3779b97f4a7c15) >>> 0; return h;
}
```

